1567→            btn2.classList.toggle('scr-unit-btn--active', btn2.dataset.unit === inlineUnit);
1568→          });
1569→          if (head && body) renderInlineTable(data, inlineUnit, head, body);
1570→        });
1571→      }
1572→      trackEvent('view', { sizeChartId: data.id });
1573→    });
1574→  }
1575→
1576→  function renderInlineTable(data, unit, head, body) {
1577→    var isMetric = unit === 'cm';
1578→    var conv = 2.54;
1579→    var srcUnit = (data.units && data.units.default) || 'in';
1580→    var hRow = '<tr>';
1581→    (data.headers || []).forEach(function (h) { hRow += '<th scope="col">' + escapeHtml(h) + '</th>'; });
1582→    hRow += '</tr>';
1583→    head.innerHTML = hRow;
1584→    var bHtml = '';
1585→    (data.rows || []).forEach(function (row) {
1586→      bHtml += '<tr>';
1587→      (data.headers || []).forEach(function (h, i) {
1588→        var cell = row[h] !== undefined ? row[h] : '';
1589→        if (i > 0) {
1590→          var num = parseFloat(cell);
1591→          if (!isNaN(num)) {
1592→            if (isMetric && srcUnit === 'in') cell = (num * conv).toFixed(1);
1593→            else if (!isMetric && srcUnit === 'cm') cell = (num / conv).toFixed(1);
1594→          }
1595→        }
1596→        var tag = i === 0 ? 'th scope="row"' : 'td';
1597→        var closeTag = i === 0 ? 'th' : 'td';
1598→        bHtml += '<' + tag + '>' + escapeHtml(String(cell)) + '</' + closeTag + '>';
1599→      });
1600→      bHtml += '</tr>';
1601→    });
1602→    body.innerHTML = bHtml;
1603→  }
1604→
1605→  // ── Bootstrap ──────────────────────────────────────────────────────────────
1606→  function init() {
1607→    // Try cache first for instant first paint
1608→    var cached = getCached();
1609→    if (cached) {
1610→      applyConfig(cached);
1611→    } else {
1612→      // Default trigger shown immediately while config loads
1613→      renderTrigger(null);
1614→    }
1615→    // Always fetch fresh config (async, non-blocking)
1616→    apiFetch(APP_BASE + '/api/widget-config?shop=' + encodeURIComponent(SHOP))
1617→      .then(function (resp) {
1618→        if (resp && resp.config) {
1619→          setCache(resp.config);
1620→          applyConfig(resp.config);
1621→        }
1622→      });
1623→  }
1624→
1625→  // Run after DOM is ready
1626→  if (document.readyState === 'loading') {
1627→    document.addEventListener('DOMContentLoaded', init);
1628→  } else {
1629→    init();
1630→  }
1631→
1632→})();
1633→</script>
1634→
1635→{% schema %}
1636→{
1637→  "name": "Size Chart",
1638→  "target": "section",
1639→  "settings": [
1640→    {
1641→      "type": "select",
1642→      "id": "display_mode",
1643→      "label": "Display Mode",
1644→      "options": [
1645→        { "value": "popup",  "label": "Popup (button opens modal)" },
1646→        { "value": "inline", "label": "Inline (chart shown on page)" },
1647→        { "value": "both",   "label": "Both (button + inline)" }
1648→      ],
1649→      "default": "popup"
1650→    },
1651→    {
1652→      "type": "select",
1653→      "id": "trigger_style",
1654→      "label": "Trigger Style",
1655→      "options": [
1656→        { "value": "button", "label": "Button" },
1657→        { "value": "link",   "label": "Text Link" },
1658→        { "value": "tab",    "label": "Side Tab" }
1659→      ],
1660→      "default": "button"
1661→    },
1662→    {
