1664→      "id": "button_text",
1665→      "label": "Button / Link Text",
1666→      "default": "Size Guide"
1667→    },
1668→    {
1669→      "type": "color",
1670→      "id": "primary_color",
1671→      "label": "Primary Color",
1672→      "default": "#000000"
1673→    },
1674→    {
1675→      "type": "color",
1676→      "id": "background_color",
1677→      "label": "Background Color",
1678→      "default": "#ffffff"
1679→    },
1680→    {
1681→      "type": "color",
1682→      "id": "text_color",
1683→      "label": "Text Color",
1684→      "default": "#111111"
1685→    },
1686→    {
1687→      "type": "range",
