<script>
(function () {
  'use strict';

  // ── Constants ──────────────────────────────────────────────────────────────
  var BLOCK_ID    = '{{ block_id }}';
  var SHOP        = '{{ shop_domain }}';
  var PRODUCT_ID  = '{{ product_id }}';
  var CACHE_KEY   = 'scr_config_' + SHOP;
  var CACHE_TTL   = 5 * 60 * 1000;

  // Determine app origin: prefer environment variable injected at build time,
  // fall back to the Shopify app proxy path (/apps/size-chart-recommender).
  // During local dev the CLI sets window.Shopify.routes, but for production
  // we rely on the app proxy which is configured in shopify.app.toml.
  // Since API routes have CORS * we can call the absolute app URL directly.
  // We derive it from the data attribute set by Liquid in the root element.
  var rootEl = document.getElementById('scr-root-' + BLOCK_ID);
  // Use window.location to build absolute origin — the app proxy forwards
  // requests from /apps/<handle> to the app server. If the merchant's theme
  // is on a custom domain, the proxy still lives on the myshopify.com domain.
  // We keep it simple: call relative paths through the app proxy.
  var APP_BASE = '/apps/size-chart-recommender';

  // ── Helpers ────────────────────────────────────────────────────────────────
  function $(id) { return document.getElementById(id); }

  function apiFetch(url, opts, timeoutMs) {
    timeoutMs = timeoutMs || 4000;
    var ctrl = new AbortController();
    var timer = setTimeout(function () { ctrl.abort(); }, timeoutMs);
    var fetchOpts = Object.assign({ signal: ctrl.signal }, opts || {});
    return fetch(url, fetchOpts)
      .then(function (r) {
        clearTimeout(timer);
        return r.ok ? r.json() : null;
      })
      .catch(function () {
        clearTimeout(timer);
        return null;
      });
  }

  function getCached() {
    try {
      var raw = localStorage.getItem(CACHE_KEY);
      if (!raw) return null;
      var obj = JSON.parse(raw);
      if (Date.now() - obj.ts < CACHE_TTL) return obj.data;
      localStorage.removeItem(CACHE_KEY);
      return null;
    } catch (e) { return null; }
  }

  function setCache(data) {
    try { localStorage.setItem(CACHE_KEY, JSON.stringify({ data: data, ts: Date.now() })); }
    catch (e) { /* storage full — ignore */ }
  }

  function trackEvent(eventType, extra) {
    var body = Object.assign(
      { shop: SHOP, eventType: eventType, productId: PRODUCT_ID },
      extra || {}
    );
    // Fire-and-forget, never block the user
    apiFetch(APP_BASE + '/api/analytics-event', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    }, 5000);
  }

  function escapeHtml(str) {
    var d = document.createElement('div');
    d.appendChild(document.createTextNode(str));
    return d.innerHTML;
  }

  // ── Read block settings baked in by Liquid ─────────────────────────────────
  var displayMode   = rootEl ? rootEl.dataset.displayMode  : 'popup';
  var triggerStyle  = rootEl ? rootEl.dataset.triggerStyle : 'button';
  var buttonText    = rootEl ? rootEl.dataset.buttonText   : 'Size Guide';
  var primaryColor  = rootEl ? rootEl.dataset.primaryColor : '#000000';
  var bgColor       = rootEl ? rootEl.dataset.bgColor      : '#ffffff';
  var textColor     = rootEl ? rootEl.dataset.textColor    : '#111111';
  var borderRadius  = rootEl ? (rootEl.dataset.borderRadius + 'px') : '8px';

  // Apply CSS variables immediately so there is no flash before config loads
  if (rootEl) {
    rootEl.style.setProperty('--scr-primary',   primaryColor);
    rootEl.style.setProperty('--scr-bg',        bgColor);
    rootEl.style.setProperty('--scr-text',      textColor);
    rootEl.style.setProperty('--scr-radius',    borderRadius);
  }

  // ── Modal & panel state ────────────────────────────────────────────────────
  var modalEl      = $('scr-modal-' + BLOCK_ID);
  var triggerWrap  = $('scr-trigger-' + BLOCK_ID);
  var inlineWrap   = $('scr-inline-' + BLOCK_ID);
  var tabBar       = $('scr-tabs-' + BLOCK_ID);
  var tabChart     = $('scr-tab-chart-' + BLOCK_ID);
  var tabRec       = $('scr-tab-rec-' + BLOCK_ID);
  var panelChart   = $('scr-panel-chart-' + BLOCK_ID);
  var panelRec     = $('scr-panel-rec-' + BLOCK_ID);

  // Chart panel elements
  var unitToggle   = $('scr-unit-toggle-' + BLOCK_ID);
  var chartLoading = $('scr-chart-loading-' + BLOCK_ID);
  var chartError   = $('scr-chart-error-' + BLOCK_ID);
  var tableWrap    = $('scr-table-wrap-' + BLOCK_ID);
  var tableHead    = $('scr-table-head-' + BLOCK_ID);
  var tableBody    = $('scr-table-body-' + BLOCK_ID);
  var scrollHint   = $('scr-scroll-hint-' + BLOCK_ID);

  // Recommender elements
  var recForm      = $('scr-rec-form-' + BLOCK_ID);
  var heightInput  = $('scr-height-' + BLOCK_ID);
  var weightInput  = $('scr-weight-' + BLOCK_ID);
  var heightUnit   = $('scr-height-unit-' + BLOCK_ID);
  var weightUnit   = $('scr-weight-unit-' + BLOCK_ID);
  var heightErr    = $('scr-height-err-' + BLOCK_ID);
  var weightErr    = $('scr-weight-err-' + BLOCK_ID);
  var submitBtn    = $('scr-rec-submit-' + BLOCK_ID);
  var submitText   = submitBtn ? submitBtn.querySelector('.scr-submit-text') : null;
  var submitSpinner= submitBtn ? submitBtn.querySelector('.scr-submit-spinner') : null;
  var formErr      = $('scr-rec-form-error-' + BLOCK_ID);
  var resultEl     = $('scr-rec-result-' + BLOCK_ID);
  var resultSize   = $('scr-result-size-' + BLOCK_ID);
  var resultMsg    = $('scr-result-msg-' + BLOCK_ID);
  var resultAlts   = $('scr-result-alts-' + BLOCK_ID);
  var altsList     = $('scr-alts-list-' + BLOCK_ID);
  var redoBtn      = $('scr-redo-btn-' + BLOCK_ID);

  // Runtime state
  var chartData    = null; // loaded chart payload
  var currentUnit  = 'in'; // active display unit
  var isOpen       = false;
  var lastFocus    = null; // element that opened the modal

  // ── Move modal to <body> to avoid stacking-context issues ──────────────────
  if (modalEl && modalEl.parentNode !== document.body) {
    document.body.appendChild(modalEl);
  }

  // ── Open / close ───────────────────────────────────────────────────────────
  function openModal() {
    if (!modalEl || isOpen) return;
    isOpen = true;
    lastFocus = document.activeElement;
    modalEl.removeAttribute('hidden');
    modalEl.focus();
    document.body.style.overflow = 'hidden';
