  function renderTrigger(config) {
    if (!triggerWrap) return;
    var style  = (config && config.triggerType) || triggerStyle;
    var label  = (config && config.buttonText)  || buttonText;
    var btn;

    if (style === 'link') {
      btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'scr-link-trigger';
      btn.textContent = label;
      btn.setAttribute('aria-haspopup', 'dialog');
