  function showChartError(msg) {
    if (chartLoading) chartLoading.style.display = 'none';
    if (chartError) {
      chartError.removeAttribute('hidden');
      var p = chartError.querySelector('.scr-error-text');
      if (p && msg) p.textContent = msg;
    }
    if (tableWrap) tableWrap.setAttribute('hidden', '');
  }

  function renderTable(data, unit) {
    if (!tableHead || !tableBody) return;
    var headers = data.headers || [];
    var rows    = data.rows    || [];
    var isMetric = unit === 'cm';
    var convFactor = 2.54;

    // Build header row
    var headTr = '<tr>';
    headers.forEach(function (h) {
      headTr += '<th scope="col">' + escapeHtml(h) + '</th>';
    });
    headTr += '</tr>';
    tableHead.innerHTML = headTr;

    // Build body rows
    var bodyHtml = '';
    rows.forEach(function (row) {
      bodyHtml += '<tr>';
      headers.forEach(function (h, i) {
        var cell = row[h] !== undefined ? row[h] : '';
        // Convert numeric measurement columns when unit changes
        // Skip first column (Size label) and non-numeric cells
        if (i > 0 && isMetric) {
          var num = parseFloat(cell);
          if (!isNaN(num)) {
            // Check if source unit is 'in'; if chart is already cm, skip
            var srcUnit = (data.units && data.units.default) || 'in';
            if (srcUnit === 'in') {
              cell = (num * convFactor).toFixed(1);
            }
          }
        } else if (i > 0 && !isMetric) {
          var num2 = parseFloat(cell);
          if (!isNaN(num2)) {
            var srcUnit2 = (data.units && data.units.default) || 'in';
            if (srcUnit2 === 'cm') {
              cell = (num2 / convFactor).toFixed(1);
            }
          }
        }
        var tag = i === 0 ? 'th scope="row"' : 'td';
        var closeTag = i === 0 ? 'th' : 'td';
        bodyHtml += '<' + tag + '>' + escapeHtml(String(cell)) + '</' + closeTag + '>';
      });
      bodyHtml += '</tr>';
    });
    tableBody.innerHTML = bodyHtml;

    // Show scroll hint only when table overflows container
    if (scrollHint) {
      var tableEl = tableBody.closest('.scr-table-scroll');
      if (tableEl && tableEl.scrollWidth > tableEl.clientWidth) {
        scrollHint.style.display = '';
      } else {
        scrollHint.style.display = 'none';
      }
    }
  }

  function showTable(data) {
    chartData = data;
    if (chartLoading) chartLoading.style.display = 'none';
    if (chartError)   chartError.setAttribute('hidden', '');
    if (tableWrap)    tableWrap.removeAttribute('hidden');

    // Unit toggle — show only if both units available
    var available = data.units && data.units.available;
    if (unitToggle && Array.isArray(available) && available.length > 1) {
      unitToggle.removeAttribute('hidden');
      currentUnit = (data.units && data.units.default) || 'in';
      // Mark active button
      var unitBtns = unitToggle.querySelectorAll('.scr-unit-btn');
      unitBtns.forEach(function (b) {
        b.classList.toggle('scr-unit-btn--active', b.dataset.unit === currentUnit);
        b.setAttribute('aria-pressed', b.dataset.unit === currentUnit ? 'true' : 'false');
      });
    }

    renderTable(data, currentUnit);
    trackEvent('view', { sizeChartId: data.id });
  }

  function loadChart() {
    showChartLoading();
    var url = APP_BASE + '/api/size-chart?shop=' + encodeURIComponent(SHOP) + '&productId=' + encodeURIComponent(PRODUCT_ID);
    apiFetch(url)
      .then(function (resp) {
        if (!resp) {
          showChartError('Failed to load size chart. Please try again.');
          return;
        }
        if (resp.error) {
          showChartError(resp.error === 'No size chart found for the given product'
            ? 'No size chart is available for this product.'
            : resp.error);
          return;
        }
        // api.size-chart returns { id, name, category, type, data: { headers, units, rows } }
        var nested = resp.data;
        if (!nested || !nested.headers || nested.headers.length === 0) {
          showChartError('No size chart is available for this product.');
          return;
        }
        // Flatten: merge outer id/name into the nested data object for convenience
        var data = Object.assign({ id: resp.id, name: resp.name, category: resp.category }, nested);
        showTable(data);
      });
  }

  // ── Unit toggle ────────────────────────────────────────────────────────────
  if (unitToggle) {
    unitToggle.addEventListener('click', function (e) {
      var btn = e.target.closest('.scr-unit-btn');
      if (!btn || !chartData) return;
      currentUnit = btn.dataset.unit;
      var allBtns = unitToggle.querySelectorAll('.scr-unit-btn');
      allBtns.forEach(function (b) {
        b.classList.toggle('scr-unit-btn--active', b.dataset.unit === currentUnit);
        b.setAttribute('aria-pressed', b.dataset.unit === currentUnit ? 'true' : 'false');
      });
      renderTable(chartData, currentUnit);
    });
  }

  // ── Tabs ───────────────────────────────────────────────────────────────────
  function activateTab(tab) {
    // tab: 'chart' | 'recommender'
    var isChart = tab === 'chart';
    if (tabChart) {
      tabChart.classList.toggle('scr-tab--active', isChart);
      tabChart.setAttribute('aria-selected', isChart ? 'true' : 'false');
    }
    if (tabRec) {
      tabRec.classList.toggle('scr-tab--active', !isChart);
      tabRec.setAttribute('aria-selected', !isChart ? 'true' : 'false');
    }
    if (panelChart) {
      if (isChart) { panelChart.removeAttribute('hidden'); panelChart.classList.add('scr-panel--active'); }
      else         { panelChart.setAttribute('hidden', ''); panelChart.classList.remove('scr-panel--active'); }
    }
    if (panelRec) {
      if (!isChart) { panelRec.removeAttribute('hidden'); panelRec.classList.add('scr-panel--active'); }
      else          { panelRec.setAttribute('hidden', ''); panelRec.classList.remove('scr-panel--active'); }
    }
  }

  if (tabBar) {
    tabBar.addEventListener('click', function (e) {
      var btn = e.target.closest('.scr-tab');
      if (!btn) return;
      activateTab(btn.dataset.tab);
    });
    // Arrow key navigation within tab list
    tabBar.addEventListener('keydown', function (e) {
      var tabs = Array.from(tabBar.querySelectorAll('.scr-tab'));
      var idx  = tabs.indexOf(document.activeElement);
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        e.preventDefault();
        var next = tabs[(idx + 1) % tabs.length];
        next.focus(); next.click();
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        e.preventDefault();
        var prev = tabs[(idx - 1 + tabs.length) % tabs.length];
        prev.focus(); prev.click();
      }
    });
  }

  // ── Recommender form ───────────────────────────────────────────────────────
  function setSubmitting(on) {
    if (!submitBtn) return;
    submitBtn.disabled = on;
    if (submitText)   submitText.textContent = on ? 'Calculating…' : 'Find My Size';
    if (submitSpinner) {
      if (on) submitSpinner.removeAttribute('hidden');
      else    submitSpinner.setAttribute('hidden', '');
    }
  }

  function showFieldError(inputEl, errEl, msg) {
    if (inputEl) inputEl.setAttribute('aria-invalid', 'true');
    if (errEl) {
      errEl.textContent = msg;
      errEl.removeAttribute('hidden');
    }
  }

  function clearFieldError(inputEl, errEl) {
    if (inputEl) inputEl.removeAttribute('aria-invalid');
    if (errEl) { errEl.textContent = ''; errEl.setAttribute('hidden', ''); }
  }

  function showFormError(msg) {
    if (formErr) { formErr.textContent = msg; formErr.removeAttribute('hidden'); }
  }

  function clearFormError() {
    if (formErr) { formErr.textContent = ''; formErr.setAttribute('hidden', ''); }
  }

  // Update height/weight unit hints when measurement system changes
  if (recForm) {
    recForm.addEventListener('change', function (e) {
      if (e.target.name !== 'unit') return;
      var isMetric = e.target.value === 'metric';
      if (heightUnit) heightUnit.textContent = isMetric ? '(cm)' : '(in)';
      if (weightUnit) weightUnit.textContent = isMetric ? '(kg)' : '(lbs)';
      if (heightInput) {
        heightInput.min   = isMetric ? '100' : '40';
        heightInput.max   = isMetric ? '250' : '98';
        heightInput.placeholder = isMetric ? '170' : '67';
      }
      if (weightInput) {
        weightInput.min   = isMetric ? '30'  : '66';
        weightInput.max   = isMetric ? '300' : '660';
        weightInput.placeholder = isMetric ? '65' : '143';
      }
    });

    recForm.addEventListener('submit', function (e) {
      e.preventDefault();
      clearFormError();
      clearFieldError(heightInput, heightErr);
      clearFieldError(weightInput, weightErr);

      var formData = new FormData(recForm);
      var unit     = formData.get('unit');
      var height   = parseFloat(formData.get('height'));
      var weight   = parseFloat(formData.get('weight'));
      var gender   = formData.get('gender');
      var bodyType = formData.get('bodyType');

      // Validate
      var valid = true;
      var isMetric = unit === 'metric';
      var minH = isMetric ? 100 : 40;
      var maxH = isMetric ? 250 : 98;
      var minW = isMetric ? 30  : 66;
      var maxW = isMetric ? 300 : 660;

      if (isNaN(height) || height < minH || height > maxH) {
        showFieldError(heightInput, heightErr,
          'Enter a height between ' + minH + ' and ' + maxH + (isMetric ? ' cm' : ' inches'));
        valid = false;
      }
      if (isNaN(weight) || weight < minW || weight > maxW) {
        showFieldError(weightInput, weightErr,
          'Enter a weight between ' + minW + ' and ' + maxW + (isMetric ? ' kg' : ' lbs'));
        valid = false;
      }
      if (!valid) return;

      if (!chartData || !chartData.id) {
        showFormError('Please open the Size Chart tab first to load chart data.');
        return;
      }

      setSubmitting(true);

      var payload = {
        shop: SHOP,
        chartId: chartData.id,
        height: height,
        weight: weight,
        unit: unit,
        gender: gender,
        bodyType: bodyType
      };

      apiFetch(APP_BASE + '/api/recommend', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })
        .then(function (resp) {
          setSubmitting(false);
          if (!resp) { showFormError('Unable to get a recommendation. Please try again.'); return; }
          if (resp.error) { showFormError(resp.error); return; }
          showResult(resp);
          trackEvent('recommend', { sizeChartId: chartData.id, size: resp.recommendedSize });
        })
        .catch(function () {
          setSubmitting(false);
          showFormError('An unexpected error occurred. Please try again.');
        });
    });
  }

  function showResult(resp) {
    if (!resultEl) return;
    // Hide form, show result
    if (recForm) recForm.style.display = 'none';
    resultEl.removeAttribute('hidden');
    if (resultSize) resultSize.textContent = resp.recommendedSize || '?';
    // Confidence message
    var conf = Math.round((resp.confidence || 0) * 100);
    if (resultMsg) {
      resultMsg.textContent = conf >= 80
        ? 'Great fit! We are ' + conf + '% confident in this recommendation.'
        : conf >= 60
          ? 'Good fit. ' + conf + '% confidence — you may want to check the chart too.'
          : 'This is our best estimate, but confidence is lower (' + conf + '%). Please also check the chart.';
    }
    // Alternatives
    var alts = resp.alternatives || [];
    if (altsList && alts.length > 0) {
      var html = '';
      alts.forEach(function (alt) {
        html += '<div class="scr-alt-chip" role="listitem">'
          + '<span class="scr-alt-size">' + escapeHtml(alt.size) + '</span>'
          + '<span class="scr-alt-confidence">' + Math.round((alt.confidence || 0) * 100) + '%</span>'
          + '</div>';
      });
      altsList.innerHTML = html;
      if (resultAlts) resultAlts.removeAttribute('hidden');
    } else {
      if (resultAlts) resultAlts.setAttribute('hidden', '');
    }
  }

  // Redo button
  if (redoBtn) {
    redoBtn.addEventListener('click', function () {
      if (resultEl) resultEl.setAttribute('hidden', '');
      if (recForm)  recForm.style.display = '';
      clearFormError();
    });
  }

  // ── Widget config load ─────────────────────────────────────────────────────
  function applyConfig(config) {
    if (!config) return;
    // Override CSS vars from server config (may differ from block settings)
    if (rootEl) {
      if (config.primaryColor)    rootEl.style.setProperty('--scr-primary', config.primaryColor);
      if (config.backgroundColor) rootEl.style.setProperty('--scr-bg',      config.backgroundColor);
      if (config.textColor)       rootEl.style.setProperty('--scr-text',     config.textColor);
      if (config.borderRadius)    rootEl.style.setProperty('--scr-radius',   config.borderRadius + 'px');
      if (config.successColor)    rootEl.style.setProperty('--scr-success',  config.successColor);
      if (config.errorColor)      rootEl.style.setProperty('--scr-error',    config.errorColor);
    }
    if (modalEl) {
      if (config.primaryColor)    modalEl.style.setProperty('--scr-primary', config.primaryColor);
      if (config.backgroundColor) modalEl.style.setProperty('--scr-bg',      config.backgroundColor);
      if (config.textColor)       modalEl.style.setProperty('--scr-text',    config.textColor);
      if (config.borderRadius)    modalEl.style.setProperty('--scr-radius',  config.borderRadius + 'px');
      if (config.successColor)    modalEl.style.setProperty('--scr-success', config.successColor);
      if (config.errorColor)      modalEl.style.setProperty('--scr-error',   config.errorColor);
    }
    // Update modal title
    if (config.heading) {
      var titleEl = $('scr-modal-title-' + BLOCK_ID);
      if (titleEl) titleEl.textContent = config.heading;
    }
    // Hide recommender tab if disabled
    if (!config.showRecommender) {
      if (tabRec)   tabRec.setAttribute('hidden', '');
      if (panelRec) panelRec.setAttribute('hidden', '');
    } else {
      if (tabRec)   tabRec.removeAttribute('hidden');
    }
    // Display mode
    var mode = config.displayMode || displayMode;
    if ((mode === 'inline' || mode === 'both') && inlineWrap) {
      inlineWrap.style.display = '';
      loadInline();
    }
    // Render trigger for popup/both modes
    if (mode !== 'inline') {
      renderTrigger(config);
    }
    // Apply custom CSS if provided
    if (config.customCss) {
      var styleTag = document.createElement('style');
      // Basic sanitization: strip </style> to prevent injection
      styleTag.textContent = config.customCss.replace(/<\/style>/gi, '');
      document.head.appendChild(styleTag);
    }
  }

  // Inline mode: render the chart directly in the page (no popup)
  function loadInline() {
    if (!inlineWrap) return;
    // Clone the table structure into the inline container
    inlineWrap.innerHTML =
      '<div class="scr-unit-toggle" id="scr-inline-unit-' + BLOCK_ID + '" hidden>' +
        '<span class="scr-unit-label">Units:</span>' +
        '<div class="scr-unit-btn-group" role="group" aria-label="Units">' +
          '<button class="scr-unit-btn scr-unit-btn--active" data-unit="in" type="button">in</button>' +
          '<button class="scr-unit-btn" data-unit="cm" type="button">cm</button>' +
        '</div>' +
      '</div>' +
      '<div class="scr-loading" id="scr-inline-loading-' + BLOCK_ID + '">' +
        '<div class="scr-spinner" aria-hidden="true"></div>' +
        '<p class="scr-loading-text">Loading size chart\u2026</p>' +
      '</div>' +
      '<div class="scr-error" id="scr-inline-error-' + BLOCK_ID + '" hidden><p class="scr-error-text">No size chart available.</p></div>' +
      '<div class="scr-table-scroll" id="scr-inline-table-' + BLOCK_ID + '" hidden tabindex="0" role="region" aria-label="Size chart">' +
        '<table class="scr-table"><thead id="scr-inline-head-' + BLOCK_ID + '"></thead><tbody id="scr-inline-body-' + BLOCK_ID + '"></tbody></table>' +
      '</div>';

    var url = APP_BASE + '/api/size-chart?shop=' + encodeURIComponent(SHOP) + '&productId=' + encodeURIComponent(PRODUCT_ID);
    apiFetch(url).then(function (resp) {
      var loading = $('scr-inline-loading-' + BLOCK_ID);
      var error   = $('scr-inline-error-' + BLOCK_ID);
      var tableScroll = $('scr-inline-table-' + BLOCK_ID);
      var head    = $('scr-inline-head-' + BLOCK_ID);
      var body    = $('scr-inline-body-' + BLOCK_ID);
      var uToggle = $('scr-inline-unit-' + BLOCK_ID);

      if (loading) loading.style.display = 'none';
      if (!resp || resp.error || !resp.data || !resp.data.headers) {
        if (error) error.removeAttribute('hidden');
        return;
      }
      if (tableScroll) tableScroll.removeAttribute('hidden');
      // Flatten nested data into a convenient object
      var data = Object.assign({ id: resp.id, name: resp.name }, resp.data);
      if (head && body) {
        var hRow = '<tr>';
        (data.headers || []).forEach(function (h) { hRow += '<th scope="col">' + escapeHtml(h) + '</th>'; });
        hRow += '</tr>';
        head.innerHTML = hRow;
        var bHtml = '';
        (data.rows || []).forEach(function (row) {
          bHtml += '<tr>';
          (data.headers || []).forEach(function (h, i) {
            var cell = row[h] !== undefined ? row[h] : '';
            var tag = i === 0 ? 'th scope="row"' : 'td';
            var closeTag = i === 0 ? 'th' : 'td';
            bHtml += '<' + tag + '>' + escapeHtml(String(cell)) + '</' + closeTag + '>';
          });
          bHtml += '</tr>';
        });
        body.innerHTML = bHtml;
      }
      // Unit toggle
      if (uToggle && data.units && Array.isArray(data.units.available) && data.units.available.length > 1) {
        uToggle.removeAttribute('hidden');
        var inlineUnit = data.units.default || 'in';
        uToggle.addEventListener('click', function (e2) {
          var b = e2.target.closest('.scr-unit-btn');
          if (!b) return;
          inlineUnit = b.dataset.unit;
          uToggle.querySelectorAll('.scr-unit-btn').forEach(function (btn2) {
            btn2.classList.toggle('scr-unit-btn--active', btn2.dataset.unit === inlineUnit);
          });
          if (head && body) renderInlineTable(data, inlineUnit, head, body);
        });
      }
      trackEvent('view', { sizeChartId: data.id });
    });
  }

  function renderInlineTable(data, unit, head, body) {
    var isMetric = unit === 'cm';
    var conv = 2.54;
    var srcUnit = (data.units && data.units.default) || 'in';
    var hRow = '<tr>';
    (data.headers || []).forEach(function (h) { hRow += '<th scope="col">' + escapeHtml(h) + '</th>'; });
    hRow += '</tr>';
    head.innerHTML = hRow;
    var bHtml = '';
    (data.rows || []).forEach(function (row) {
      bHtml += '<tr>';
      (data.headers || []).forEach(function (h, i) {
        var cell = row[h] !== undefined ? row[h] : '';
        if (i > 0) {
          var num = parseFloat(cell);
          if (!isNaN(num)) {
            if (isMetric && srcUnit === 'in') cell = (num * conv).toFixed(1);
            else if (!isMetric && srcUnit === 'cm') cell = (num / conv).toFixed(1);
          }
        }
        var tag = i === 0 ? 'th scope="row"' : 'td';
        var closeTag = i === 0 ? 'th' : 'td';
        bHtml += '<' + tag + '>' + escapeHtml(String(cell)) + '</' + closeTag + '>';
      });
      bHtml += '</tr>';
    });
    body.innerHTML = bHtml;
  }

  // ── Bootstrap ──────────────────────────────────────────────────────────────
  function init() {
    // Try cache first for instant first paint
    var cached = getCached();
    if (cached) {
      applyConfig(cached);
    } else {
      // Default trigger shown immediately while config loads
      renderTrigger(null);
    }
    // Always fetch fresh config (async, non-blocking)
    apiFetch(APP_BASE + '/api/widget-config?shop=' + encodeURIComponent(SHOP))
      .then(function (resp) {
        if (resp && resp.config) {
          setCache(resp.config);
          applyConfig(resp.config);
        }
      });
  }

  // Run after DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();
</script>

{% schema %}
{
  "name": "Size Chart",
  "target": "section",
  "settings": [
    {
      "type": "select",
      "id": "display_mode",
      "label": "Display Mode",
      "options": [
        { "value": "popup",  "label": "Popup (button opens modal)" },
        { "value": "inline", "label": "Inline (chart shown on page)" },
        { "value": "both",   "label": "Both (button + inline)" }
      ],
      "default": "popup"
    },
    {
      "type": "select",
      "id": "trigger_style",
      "label": "Trigger Style",
      "options": [
        { "value": "button", "label": "Button" },
        { "value": "link",   "label": "Text Link" },
        { "value": "tab",    "label": "Side Tab" }
      ],
      "default": "button"
    },
    {
      "type": "text",
      "id": "button_text",
      "label": "Button / Link Text",
      "default": "Size Guide"
    },
    {
      "type": "color",
      "id": "primary_color",
      "label": "Primary Color",
      "default": "#000000"
    },
    {
      "type": "color",
      "id": "background_color",
      "label": "Background Color",
      "default": "#ffffff"
    },
    {
      "type": "color",
      "id": "text_color",
      "label": "Text Color",
      "default": "#111111"
    },
    {
      "type": "range",
      "id": "border_radius",
      "label": "Border Radius",
      "min": 0,
      "max": 24,
      "step": 1,
      "default": 8,
      "unit": "px"
    }
  ],
  "presets": [
    {
      "name": "Size Chart",
      "settings": {
        "display_mode": "popup",
        "trigger_style": "button",
        "button_text": "Size Guide"
      }
    }
  ]
}
{% endschema %}

content.content:
  1→{% comment %}
  2→  Size Chart & Recommender — Standalone Size Recommender App Block
  3→  A compact "Find My Size" widget that can be placed anywhere on a product page.
  4→  Does not show the full size chart table — only the AI recommendation form.
  5→  Pairs well with the size-chart block placed elsewhere on the same page.
  6→{% endcomment %}
  7→
  8→{% liquid
  9→  assign block_id   = block.id | replace: '-', '_'
 10→  assign shop_domain = shop.permanent_domain
 11→  assign product_id  = product.id | append: ''
 12→%}
