 19→  data-product-id="{{ product_id }}"
 20→  data-primary-color="{{ block.settings.primary_color }}"
 21→  data-bg-color="{{ block.settings.background_color }}"
 22→  data-text-color="{{ block.settings.text_color }}"
 23→  data-border-radius="{{ block.settings.border_radius }}"
 24→>
