 26→  <div class="scrr-header">
 27→    <button
 28→      class="scrr-toggle"
 29→      type="button"
 30→      aria-expanded="false"
 31→      aria-controls="scrr-body-{{ block_id }}"
 32→      id="scrr-toggle-{{ block_id }}"
 33→    >
 34→      <span class="scrr-toggle-icon" aria-hidden="true">
 35→        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" focusable="false">
 36→          <circle cx="12" cy="12" r="10"/>
 37→          <line x1="12" y1="8" x2="12" y2="12"/>
