 42→      <span class="scrr-chevron" aria-hidden="true">
 43→        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" focusable="false">
 44→          <polyline points="6 9 12 15 18 9"/>
 45→        </svg>
