 55→    aria-labelledby="scrr-toggle-{{ block_id }}"
 56→    hidden
 57→  >
 58→    {%- comment -%} Not-enabled notice (shown when recommender is off for this shop) {%- endcomment -%}
 59→    <div class="scrr-disabled-notice" id="scrr-disabled-{{ block_id }}" hidden role="alert">
 60→      <p>{{ 'products.size_chart.recommender_unavailable' | t | default: 'The size recommender is not available for this store.' }}</p>
 61→    </div>
