 65→      {%- comment -%} Measurement system {%- endcomment -%}
 66→      <fieldset class="scrr-fieldset">
 67→        <legend class="scrr-legend">{{ 'products.size_chart.measurement_system' | t | default: 'Measurement System' }}</legend>
 68→        <div class="scrr-radio-group">
